arguments.command:
perl -e '
sub crc32 {
    my $data = shift;
    my $crc = 0xFFFFFFFF;
    for my $byte (unpack("C*", $data)) {
        $crc ^= $byte;
        for (1..8) {
            $crc = ($crc >> 1) ^ (0xEDB88320 & -($crc & 1));
        }
    }
    return $crc ^ 0xFFFFFFFF;
}
my $candidate = "PASSWORD=8XDP5Q2RT9ZK7VB3BV4WW54\n";
printf "Length: %d\n", length($candidate);
printf "CRC32: %08x\n", crc32($candidate) & 0xFFFFFFFF;
print "Target: b0725dc4\n";
'

